import{z as C,x as E,o as s,c as P,q as o,j as i,D as t,d as r,s as T,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"HTTP/3","description":"","frontmatter":{"title":"HTTP/3","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http3.md","filePath":"cs/http3.md","lastUpdated":1791063341000}'),p={name:"cs/http3.md"};function A(d,a,B,H,h,D){const l=E("Mermaid");return s(),P("div",null,[a[2]||(a[2]=o('<h1 id="http-3" tabindex="-1">HTTP/3 <a class="header-anchor" href="#http-3" aria-label="Permalink to &quot;HTTP/3&quot;">​</a></h1><div class="epigraph"><p>把 HTTP 语义映到 QUIC 流：每请求一流，头用 QPACK；运输是 UDP 上的加密多流，不再套 TLS-over-TCP。</p><footer>—— 据 RFC 9114 HTTP/3；RFC 9204 QPACK 整理</footer></div><p><a href="/cs/hol-blocking">队头对照</a> 指向 QUIC。<a href="/cs/quic-streams-0rtt">QUIC 流</a> 已备运输。主干语义仍是 <a href="/cs/http-semantics">RFC 9110</a>。缺口是 <strong>HTTP/3 映射</strong>：SETTINGS、QPACK、Alt-Svc 发现。本课不把 Cookie 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTP/2 帧不能原样放进 QUIC：流模型与头压缩依赖 TCP 有序。H3：请求体走 QUIC 流，控制流另开，QPACK 用独立流传表更新以免头压缩再引入 HOL。发现：DNS HTTPS RR 或 Alt-Svc 从 H1/H2 升级。0-RTT 可早发 GET，须幂等。</p><p>不要把 H3 写成新方法新状态码。</p><p><span class="marginnote">RFC 9114。中间盒对 UDP 443 的态度决定能否用上上一课的迁移。</span></p><h3 id="语义不变运输换" tabindex="-1">语义不变运输换 <a class="header-anchor" href="#语义不变运输换" aria-label="Permalink to &quot;语义不变运输换&quot;">​</a></h3><p>HPACK 在 H2 里敢激进更新字典，靠的是 TCP 严格有序；QUIC 流间无序，沿用会重新引入队头阻塞——一次表更新晚到，后续流的解压全卡住。QPACK 把字典更新拆到独立单向流，头块等到所需更新确认送达才消费，压缩不再牵制数据流。发现靠 Alt-Svc 或 DNS HTTPS RR：服务器在既有连接上广告「h3 可用」，下次另起端口另起协议。UDP 不通则回退 H2。CDN 要终止 QUIC——边缘节点必须自己会说 h3，否则收益止步于回源。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三代对照：H1 文本、一连接一请求；H2 二进制帧多路复用，但全体共享一条 TCP；H3 二进制，复用建在 QUIC 流上，每请求一流互不阻塞。实现要点在发送侧：TCP 有内核代做的分段，UDP 没有，要靠 UDP GSO 一类接口一次递一大批报文给内核，否则每包一次系统调用的开销吃掉收益。</p>',11)),(s(),i(n,null,{default:t(()=>[T(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEM%5B%22RFC%209110%20%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20H3%5B%22%E6%98%A0%E5%88%B0%20QUIC%20%E6%B5%81%22%5D%0A%20%20H3%20--%3E%20QP%5B%22QPACK%20%E6%97%A0%20HOL%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20DISC%5B%22Alt-Svc%2FHTTPS%20RR%22%5D%20--%3E%20H3%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"连接迁移让移动中的 HTTP 会话活过 IP 变化：连接由 CID 标识而非四元组，Wi-Fi 换蜂窝不断流，这是上一课迁移机制的直接受益者。MSS 语义也换了位置：包大小由 QUIC 自己定并跑 PMTUD；不少部署把 BBR 设为默认 CC。Cookie 仍是语义头，下一课。CDN 边缘终止 QUIC 后，证书管理与按 CID 路由是真实运营工作量。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：CID（连接 ID）就是这条连接的「身份证号」，与 IP 地址、端口解耦。TCP 时代换网即断——身份绑在「哪台机哪个口」上；QUIC 把身份换成随机号码，手机从 Wi-Fi 切到 5G 时 IP 变了，号码没变，视频通话与下载都不中断。")],-1)),a[6]||(a[6]=e("p",null,"回退：UDP 不通则 H2。不是协议失败，是路径政策。",-1)),a[7]||(a[7]=e("p",null,"丢一个包，HTTP/2 与 HTTP/3 各冻住多少工作？",-1)),(s(),i(n,null,{default:t(()=>[T(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E4%B8%80%E4%B8%AA%E5%8C%85%E4%B8%A2%E4%BA%86%22%5D%20--%3E%20H2%5B%22H2%20over%20TCP%EF%BC%9A%E7%AD%89%E9%87%8D%E4%BC%A0%E8%A1%A5%E9%BD%90%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%0A%20%20H2%20--%3E%20ALL%5B%22%E6%89%80%E6%9C%89%E6%B5%81%E4%B8%80%E8%B5%B7%E5%81%9C%22%5D%0A%20%20L%20--%3E%20H3%5B%22QUIC%20%E6%8C%89%E6%B5%81%E7%8B%AC%E7%AB%8B%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20H3%20--%3E%20ONE%5B%22%E5%8F%AA%E6%9C%89%E8%AF%A5%E6%B5%81%E5%81%9C%EF%BC%8C%E5%85%B6%E4%BB%96%E6%B5%81%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：一条连接跑 20 个流、丢 1 个包——HTTP/2 下这 20 个流全部卡住等重传（RTT 若 50 ms，就是全体多等 50 ms）；HTTP/3 下只有数据恰好在丢包里的那个流等，其余 19 个照常走。丢包率越高，差距拉得越开，这正是移动网络的常态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 WebTransport 的全部。Cookie 与会话是下一课。后课默认：H3 = HTTP 语义 + QUIC 运输。最后一条部署现实：网络只开 TCP 443、UDP 被禁时，用户永远协商不到 H3，QUIC 的好处再大也看不见——协议可用性由路径政策决定。</p><p>下一课<a href="/cs/cookies-sessions">Cookie 与会话</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语义不变，运输换 QUIC。</li><li>QPACK 避免头压缩 HOL。</li><li>发现与 UDP 路径是部署条件。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9114；RFC 9204。</li></ul><p><span class="marginnote">常见误区：初学者容易以为 HTTP/3 发明了新的方法、状态码或缓存规则。GET 还是 GET、404 还是 404——变的只是下层「怎么把字节可靠地送到」：TCP+TLS 换成 UDP 上的 QUIC。语义层不变正是迁移成本低的根本原因。</span></p>',7))])}const I=C(p,[["render",A]]);export{c as __pageData,I as default};
